92	    /**
93	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
94	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
95	     */
96	    private static final Map<String, String> CITY_REGION = Map.of(
97	        "Sydney", "NSW",
98	        "Melbourne", "VIC",
99	        "Brisbane", "QLD");
100	
101	    /**
102	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
103	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
104	     */
105	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
106	        "NSW", new int[] {2000, 2099},
107	        "VIC", new int[] {3000, 3099},
108	        "QLD", new int[] {4000, 4099});
