110	    /**
111	     * Fixed region-to-timezone table used to derive {@link #getTimezone() timezone} from the owner's
112	     * {@link #getLocality() locality}: NSW->Australia/Sydney, VIC->Australia/Melbourne,
113	     * QLD->Australia/Brisbane. A locality not listed derives a {@code null} timezone.
114	     */
115	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
116	        "NSW", "Australia/Sydney",
117	        "VIC", "Australia/Melbourne",
118	        "QLD", "Australia/Brisbane");
