144	    /**
145	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
146	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
147	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
148	     * split by taking its leading digit as the (minimal) country code.
149	     */
150	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
151	
152	    /**
153	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
154	     * single space, then the national digits grouped in threes from the left (e.g. the stored
155	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
156	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
157	     * digit string.
158	     *
159	     * @return the human-readable telephone, or the stored value when it cannot be formatted
160	     */
161	    public String getTelephoneDisplay() {
162	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
163	            return this.telephone;
164	        }
165	        String digits = this.telephone.substring(1);
166	        String countryCode = extractCountryCode(digits);
167	        String national = digits.substring(countryCode.length());
168	        StringBuilder display = new StringBuilder("+").append(countryCode);
169	        for (int i = 0; i < national.length(); i += 3) {
170	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
171	        }
172	        return display.toString();
173	    }
174	
175	    /**
176	     * Splits the country code off an E.164 digit string (country code followed by national digits,
177	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
178	     * whose required national-number length matches the remaining digits is preferred; failing that,
179	     * the leading digit is used as the country code.
180	     *
181	     * @param digits the E.164 digits without the leading {@code '+'}
182	     * @return the country-code portion of {@code digits}
183	     */
184	    private static String extractCountryCode(String digits) {
185	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
186	            String code = entry.getKey();
187	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
188	                return code;
189	            }
190	        }
191	        return digits.substring(0, 1);
192	    }
