218	    /**
219	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
220	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
221	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
222	     * elapsed from the birth date to the registration date (defaulting to the server's current date
223	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
224	     *
225	     * @return the age band, or {@code null} when the birth date is absent
226	     */
227	    public String getAgeBand() {
228	        if (this.birthDate == null) {
229	            return null;
230	        }
231	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
232	        int years = Period.between(this.birthDate, asAt).getYears();
233	        if (years < 18) {
234	            return "MINOR";
235	        }
236	        if (years < 65) {
237	            return "ADULT";
238	        }
239	        return "SENIOR";
240	    }
