250	    /**
251	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
252	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
253	     * from the owner's own customer code and registration date; {@code null} when either is absent.
254	     *
255	     * @return the membership number, or {@code null} when it cannot be derived
256	     */
257	    public String getMembershipNumber() {
258	        if (this.customerCode == null || this.registrationDate == null) {
259	            return null;
260	        }
261	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
262	    }
263	
264	    /**
265	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
266	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
267	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
268	     *
269	     * @return the Luhn check digit, or {@code null} when the customer code is absent
270	     */
271	    public Integer getCheckDigit() {
272	        if (this.customerCode == null) {
273	            return null;
274	        }
275	        int sum = 0;
276	        boolean dbl = true;
277	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
278	            char c = this.customerCode.charAt(i);
279	            if (c < '0' || c > '9') {
280	                continue;
281	            }
282	            int d = c - '0';
283	            if (dbl) {
284	                d *= 2;
285	                if (d > 9) {
286	                    d -= 9;
287	                }
288	            }
289	            sum += d;
290	            dbl = !dbl;
291	        }
292	        return (10 - (sum % 10)) % 10;
293	    }
