295	    /**
296	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
297	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
298	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
299	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure exceeds 365 days (see
300	     * {@link #getTenureDays()}). Because a newly created owner has zero tenure, the tenure points are
301	     * never awarded at create time.
302	     *
303	     * @return the membership points, a non-negative integer
304	     */
305	    public Integer getMembershipPoints() {
306	        int points = 0;
307	        boolean hasEmail = this.email != null && !this.email.isBlank();
308	        if (hasEmail) {
309	            points += 2;
310	        }
311	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
312	        if (hasNoNamesakes) {
313	            points += 1;
314	        }
315	        if (this.householdSize != null && this.householdSize >= 3) {
316	            points += 2;
317	        }
318	        Long tenureDays = getTenureDays();
319	        if (tenureDays != null && tenureDays > 365) {
320	            points += 3;
321	        }
322	        return points;
323	    }
324	
325	    /**
326	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
327	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
328	     * for 6 or more points.
329	     *
330	     * @return the membership level, an integer from 1 to 4
331	     */
332	    public Integer getMembershipLevel() {
333	        int points = getMembershipPoints();
334	        if (points <= 1) {
335	            return 1;
336	        }
337	        if (points <= 3) {
338	            return 2;
339	        }
340	        if (points <= 5) {
341	            return 3;
342	        }
343	        return 4;
344	    }
345	
346	    /**
347	     * The owner's tenure in whole days, the number of days elapsed from the
348	     * {@link #getRegistrationDate() registration date} to the server's current date. A tenure of more
349	     * than 365 days is what raises the {@link #getMembershipLevel() membership level} to 4. Returns
350	     * {@code null} when no registration date has been set yet.
351	     *
352	     * @return the tenure in whole days, or {@code null} when the registration date is absent
353	     */
354	    public Long getTenureDays() {
355	        if (this.registrationDate == null) {
356	            return null;
357	        }
358	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
359	    }
360	
361	    /**
362	     * The owner's locality, the canonical region string. Once the owner has a
363	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
364	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
365	     * source of truth. Before the customer code is assigned (for example while a create is still
366	     * validating the postcode) it falls back to the region the code will be built from: the
367	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
368	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
369	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
370	     *
371	     * @return the canonical region string, or {@code 'UNKNOWN'}
372	     */
373	    public String getLocality() {
374	        if (this.customerCode != null) {
375	            int dash = this.customerCode.indexOf('-');
376	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
377	        }
378	        return deriveRegion();
379	    }
380	
381	    /**
382	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
383	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
384	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
385	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
386	     *
387	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
388	     */
389	    public String getTimezone() {
390	        return REGION_TIMEZONE.get(getLocality());
391	    }
392	
393	    /**
394	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
395	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
396	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
397	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
398	     * the same region for known cities but disambiguates cities that share a name.
399	     *
400	     * @return the canonical region string, or {@code 'UNKNOWN'}
401	     */
402	    private String deriveRegion() {
403	        String region = regionFromPostcode();
404	        if (region != null) {
405	            return region;
406	        }
407	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
408	    }
409	
410	    /**
411	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
412	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
413	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
414	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
415	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
416	     * owner's region, telephone and last name. Call this once at create time and store the result via
417	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
418	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
419	     *
420	     * @return the assembled customer code
421	     */
422	    public String buildCustomerCode() {
423	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
424	    }
425	
426	    /**
427	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
428	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
429	     *
430	     * @param value the value to hash
431	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
432	     */
433	    private static String sha256Hex8(String value) {
434	        try {
435	            byte[] digest = MessageDigest.getInstance("SHA-256")
436	                .digest(value.getBytes(StandardCharsets.UTF_8));
437	            StringBuilder hex = new StringBuilder(8);
438	            for (int i = 0; i < 4; i++) {
439	                hex.append(String.format("%02X", digest[i]));
440	            }
441	            return hex.toString();
442	        }
443	        catch (NoSuchAlgorithmException e) {
444	            throw new IllegalStateException("SHA-256 algorithm not available", e);
445	        }
446	    }
447	
448	    /**
449	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
450	     * absent, not a 4-digit number, or in no known range.
451	     *
452	     * @return the matching region, or {@code null}
453	     */
454	    private String regionFromPostcode() {
455	        if (this.postcode == null) {
456	            return null;
457	        }
458	        int value;
459	        try {
460	            value = Integer.parseInt(this.postcode.trim());
461	        }
462	        catch (NumberFormatException ex) {
463	            return null;
464	        }
465	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
466	            int[] range = entry.getValue();
467	            if (value >= range[0] && value <= range[1]) {
468	                return entry.getKey();
469	            }
470	        }
471	        return null;
472	    }
