485	    /**
486	     * The owner's identity key, the single derived value used for duplicate detection. It is the
487	     * owner's normalized telephone, email (empty when absent) and household id joined with
488	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
489	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
490	     * are equal, so two members of the same household with different telephones differ here and are
491	     * both allowed.
492	     *
493	     * @return the derived identity key
494	     */
495	    public String getIdentityKey() {
496	        return (this.telephone == null ? "" : this.telephone) + "|"
497	            + (this.email == null ? "" : this.email) + "|"
498	            + (this.householdId == null ? "" : this.householdId);
499	    }
