557	    /**
558	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
559	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
560	     */
561	    @PrePersist
562	    void onCreate() {
563	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
564	    }
565	
566	    /**
567	     * Resolves the effective registration date and rolls it onto a business day. An absent
568	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
569	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
570	     * becomes the following Monday, while any weekday is returned unchanged.
571	     *
572	     * <p>This is the single definition of both the defaulting and the business-day roll, used
573	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
574	     * stamps the owner and by the create endpoint that counts owners per business day.
575	     *
576	     * @param supplied the registration date from the request, or {@code null} when none was supplied
577	     * @return the effective registration date, guaranteed to fall on a business day
578	     */
579	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
580	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
581	        return switch (effective.getDayOfWeek()) {
582	            case SATURDAY -> effective.plusDays(2);
583	            case SUNDAY -> effective.plusDays(1);
584	            default -> effective;
585	        };
586	    }
