624	    /**
625	     * Return the Pet with the given name, or null if none found for this Owner.
626	     *
627	     * @param name to test
628	     * @return true if pet name is already in use
629	     */
630	    public Pet getPet(String name, boolean ignoreNew) {
631	        name = name.toLowerCase();
