32	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
33	
34	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
35	
36	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
37	        OwnerPageDto ownerPageDto = new OwnerPageDto();
38	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
39	        ownerPageDto.setPage(ownerPage.getNumber());
40	        ownerPageDto.setSize(ownerPage.getSize());
41	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
42	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
43	        return ownerPageDto;
44	    }
45	}
