59	import org.springframework.util.StringUtils;
60	import org.springframework.web.bind.annotation.CrossOrigin;
61	import org.springframework.web.bind.annotation.RequestMapping;
62	import org.springframework.web.bind.annotation.RestController;
63	import org.springframework.web.util.UriComponentsBuilder;
64	
65	import jakarta.transaction.Transactional;
66	
67	/**
68	 * @author Vitaliy Fedoriv
69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
78	     * owner's id, customer code, registration date and membership level, so the create side-effect
79	     * can be audited independently of the application log.
80	     */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    /**
92	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
93	     * and a domain containing at least one dot, with no whitespace in any segment.
94	     */
95	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
96	
97	    /**
98	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
99	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
100	     * {@code '@'}) is rejected with a 400 Bad Request.
101	     */
102	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
103	        "mailinator.com",
104	        "tempmail.com",
105	        "guerrillamail.com");
106	
107	    /**
108	     * Required national-number length per E.164 country code. A normalized telephone whose country
109	     * code appears here must carry exactly this many national digits after the code; Australia
110	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
111	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
112	     */
113	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
114	
115	    /**
116	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
117	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
118	     */
119	    private static final int MAX_OWNERS_PER_CITY = 50;
120	
121	    /**
122	     * Maximum number of owners that may be registered on a single day (by registration date). A create
123	     * attempted once this many owners already carry today's registration date is rejected with a
124	     * 429 Too Many Requests.
125	     */
126	    private static final int MAX_OWNERS_PER_DAY = 100;
127	
128	    /**
129	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
130	     * owners already carry the new owner's registration date, the created owner is flagged
131	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
132	     */
133	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
134	
135	    /**
136	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
137	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
138	     */
139	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
140	        "ST", "STREET",
141	        "RD", "ROAD",
142	        "AVE", "AVENUE");
143	
144	    /**
145	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
146	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
147	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
148	     * 4-digit postcode.
149	     */
150	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
151	        "NSW", new int[] {2000, 2099},
152	        "VIC", new int[] {3000, 3099},
153	        "QLD", new int[] {4000, 4099});
154	
155	    public OwnerRestControllerV1(ClinicService clinicService,
156	                                 OwnerMapper ownerMapper,
157	                                 PetMapper petMapper,
158	                                 VisitMapper visitMapper) {
159	        this.clinicService = clinicService;
160	        this.ownerMapper = ownerMapper;
161	        this.petMapper = petMapper;
162	        this.visitMapper = visitMapper;
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
168	        Collection<Owner> owners;
169	        if (lastName != null) {
170	            owners = this.clinicService.findOwnerByLastName(lastName);
171	        } else {
172	            owners = this.clinicService.findAllOwners();
173	        }
174	        if (owners.isEmpty()) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
193	        validateRequiredFields(ownerFieldsDto);
194	        HttpHeaders headers = new HttpHeaders();
195	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
196	        rejectFutureRegistrationDate(owner.getRegistrationDate());
197	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
198	        owner.setRegistrationDate(registrationDate);
199	        requireDailyCapacity(registrationDate);
200	        requireCityHasCapacity(owner.getCity());
201	        validatePostcode(owner);
202	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
203	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
204	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
205	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
206	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
207	        requireNoHouseholdDuplicate(owner, declaredHouseholdMember);
208	        requireUniqueIdentity(owner);
209	        flagPossibleDuplicate(owner, declaredHouseholdMember);
210	        owner.setCustomerCode(deduplicateCustomerCode(owner.buildCustomerCode()));
211	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
212	        stampHouseholdSize(owner);
213	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
214	        this.clinicService.saveOwner(owner);
215	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
216	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
217	            owner.getMembershipNumber());
218	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
219	        headers.setLocation(UriComponentsBuilder.newInstance()
220	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
221	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
222	    }
223	
224	    /**
225	     * Rejects a create whose supplied registration date is later than the server's current date. A
226	     * registration may be back-dated but never post-dated, so a future date is treated as a client
227	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
228	     * server date.
229	     *
230	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
231	     *     client omitted it
232	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
233	     */
234	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
235	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
236	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
237	        }
238	    }
239	
240	    /**
241	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
242	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
243	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
244	     * existed prior to this create.
245	     *
246	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
247	     *     a business day
248	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
249	     *     registered on that business day
250	     */
251	    private void requireDailyCapacity(LocalDate registrationDate) {
252	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
253	            throw new DailyOwnerLimitException(registrationDate);
254	        }
255	    }
256	
257	    /**
258	     * Counts the existing owners whose registration date equals the given business-day date. This is
259	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
260	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
261	     * the bulk-signup warning.
262	     *
263	     * @param registrationDate the effective business-day registration date to count against
264	     * @return the number of pre-existing owners registered on that date
265	     */
266	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
267	        return this.clinicService.findAllOwners().stream()
268	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
269	            .count();
270	    }
271	
272	    /**
273	     * Rejects an owner whose city already contains the maximum allowed number of owners
274	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
275	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
276	     * create.
277	     *
278	     * @param city the city of the owner being created
279	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
280	     */
281	    private void requireCityHasCapacity(String city) {
282	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
283	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
284	            .count();
285	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
286	            throw new CityOwnerLimitException(city);
287	        }
288	    }
289	
290	    /**
291	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
292	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
293	     * schema) that must fall within the inclusive range permitted for the region derived from the
294	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
295	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
296	     *
297	     * @param owner the owner being created, with its city and postcode set
298	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
299	     */
300	    private void validatePostcode(Owner owner) {
301	        String postcode = owner.getPostcode();
302	        if (postcode == null) {
303	            return;
304	        }
305	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
306	        if (range == null) {
307	            return;
308	        }
309	        int value = Integer.parseInt(postcode);
310	        if (value < range[0] || value > range[1]) {
311	            throw new InvalidOwnerFieldsException(List.of("postcode"));
312	        }
313	    }
314	
315	    /**
316	     * Counts the existing owners that already share the given first name and last name, compared
317	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
318	     * owners that existed prior to this create.
319	     *
320	     * @param firstName the first name of the owner being created
321	     * @param lastName the last name of the owner being created
322	     * @return the number of pre-existing namesakes
323	     */
324	    private int countNamesakes(String firstName, String lastName) {
325	        return (int) this.clinicService.findAllOwners().stream()
326	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
327	                && equalsIgnoreCase(existing.getLastName(), lastName))
328	            .count();
329	    }
330	
331	    /**
332	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
333	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
334	     *
335	     * @param a the first value, possibly {@code null}
336	     * @param b the second value, possibly {@code null}
337	     * @return whether the values are equal ignoring case
338	     */
339	    private boolean equalsIgnoreCase(String a, String b) {
340	        return a == null ? b == null : a.equalsIgnoreCase(b);
341	    }
342	
343	    /**
344	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
345	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
346	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
347	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
348	     *
349	     * @param ownerFieldsDto the submitted owner fields
350	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
351	     */
352	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
353	        List<String> invalidFields = new ArrayList<>();
354	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
355	            invalidFields.add("firstName");
356	        }
357	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
358	            invalidFields.add("lastName");
359	        }
360	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
361	            invalidFields.add("address");
362	        }
363	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
364	            invalidFields.add("city");
365	        }
366	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
367	            invalidFields.add("telephone");
368	        }
369	        if (!invalidFields.isEmpty()) {
370	            throw new InvalidOwnerFieldsException(invalidFields);
371	        }
372	    }
373	
374	    /**
375	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
376	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
377	     * what gets stored and returned.
378	     *
379	     * @param telephone the raw telephone value from the request
380	     * @return the normalized E.164 telephone number
381	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
382	     */
383	    private String normalizeTelephone(String telephone) {
384	        String e164 = toE164(telephone);
385	        if (e164 == null) {
386	            throw new InvalidOwnerFieldsException(List.of("telephone"));
387	        }
388	        return e164;
389	    }
390	
391	    /**
392	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
393	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
394	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
395	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
396	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
397	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
398	     *
399	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
400	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
401	     *
402	     * @param telephone the raw telephone value, possibly {@code null}
403	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
404	     */
405	    private String toE164(String telephone) {
406	        if (telephone == null) {
407	            return null;
408	        }
409	        String cleaned = telephone.replaceAll("[ \\-()]", "");
410	        String digits;
411	        if (cleaned.startsWith("+")) {
412	            digits = cleaned.substring(1);
413	        } else {
414	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
415	            digits = "61" + national;
416	        }
417	        if (!digits.matches("[0-9]{8,15}")) {
418	            return null;
419	        }
420	        if (!nationalNumberLengthValid(digits)) {
421	            return null;
422	        }
423	        return "+" + digits;
424	    }
425	
426	    /**
427	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
428	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
429	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
430	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
431	     * accepted, leaving only the generic total-length rule to apply.
432	     *
433	     * @param digits the E.164 digits without the leading {@code '+'}
434	     * @return {@code true} if the national-number length matches the country code's requirement
435	     */
436	    private boolean nationalNumberLengthValid(String digits) {
437	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
438	            String code = entry.getKey();
439	            if (digits.startsWith(code)) {
440	                return digits.length() - code.length() == entry.getValue();
441	            }
442	        }
443	        return true;
444	    }
445	
446	    /**
447	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
448	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
449	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
450	     * returned lower-cased.
451	     *
452	     * @param email the raw email value from the request, possibly {@code null}
453	     * @return the lower-cased email, or {@code null} when none was supplied
454	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
455	     *     its domain is on the disposable-domain blocklist
456	     */
457	    private String normalizeEmail(String email) {
458	        if (!StringUtils.hasText(email)) {
459	            return null;
460	        }
461	        String trimmed = email.trim();
462	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
463	            throw new InvalidOwnerFieldsException(List.of("email"));
464	        }
465	        String normalized = trimmed.toLowerCase(Locale.ROOT);
466	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
467	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
468	            throw new InvalidOwnerFieldsException(List.of("email"));
469	        }
470	        return normalized;
471	    }
472	
473	    /**
474	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
475	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
476	     * owner's normalized telephone, email (empty when absent) and household id joined with
477	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
478	     * owner's. Because the telephone is part of the key, two members of the same household
479	     * (same {@code householdId}) with different telephones have different identity keys and are both
480	     * allowed.
481	     *
482	     * @param owner the owner being created, with its normalized telephone, email and household id set
483	     * @throws DuplicateIdentityException if another owner already has this identity key
484	     */
485	    private void requireUniqueIdentity(Owner owner) {
486	        String identityKey = owner.getIdentityKey();
487	        boolean inUse = this.clinicService.findAllOwners().stream()
488	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
489	        if (inUse) {
490	            throw new DuplicateIdentityException(identityKey);
491	        }
492	    }
493	
494	    /**
495	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
496	     * When the computed code is unique it is returned unchanged. When it collides with an existing
497	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
498	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
499	     * so on), and that de-duplicated code is returned.
500	     *
501	     * @param customerCode the freshly computed customer code to de-duplicate
502	     * @return a customer code not held by any existing owner
503	     */
504	    private String deduplicateCustomerCode(String customerCode) {
505	        Set<String> inUse = this.clinicService.findAllOwners().stream()
506	            .map(Owner::getCustomerCode)
507	            .filter(Objects::nonNull)
508	            .collect(Collectors.toSet());
509	        if (!inUse.contains(customerCode)) {
510	            return customerCode;
511	        }
512	        int n = 2;
513	        String candidate;
514	        do {
515	            candidate = customerCode + "-" + n;
516	            n++;
517	        } while (inUse.contains(candidate));
518	        return candidate;
519	    }
520	
521	    /**
522	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
523	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
524	     * but it shares an existing owner's last name (compared case-insensitively) and postcode (both
525	     * present and equal) while carrying a different normalized telephone. When such an existing owner is
526	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
527	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
528	     * is false and {@code possibleDuplicateOf} is left unset.
529	     *
530	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
531	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
532	     *
533	     * @param owner the owner being created, with its normalized telephone and postcode set
534	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
535	     */
536	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
537	        if (declaredHouseholdMember || owner.getPostcode() == null) {
538	            owner.setPossibleDuplicate(false);
539	            return;
540	        }
541	        Integer matchId = this.clinicService.findAllOwners().stream()
542	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
543	                && owner.getPostcode().equals(existing.getPostcode())
544	                && !owner.getTelephone().equals(existing.getTelephone()))
545	            .map(Owner::getId)
546	            .min(Integer::compareTo)
547	            .orElse(null);
548	        owner.setPossibleDuplicate(matchId != null);
549	        owner.setPossibleDuplicateOf(matchId);
550	    }
551	
552	    /**
553	     * Rejects a create that would join an existing household unless it has opted in via
554	     * {@code sharesHousehold}. The household is keyed on the deterministic {@code householdId} (derived
555	     * from the normalized last name and postcode; see {@link #computeHouseholdId}), so any existing
556	     * owner carrying the same {@code householdId} is a member of the same household. When one exists and
557	     * the create has not declared household membership, the second owner is a household duplicate.
558	     *
559	     * <p>A create that declares {@code sharesHousehold} bypasses this block entirely and is created as a
560	     * declared household member.
561	     *
562	     * @param owner the owner being created, with its deterministic {@code householdId} already set
563	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
564	     * @throws DuplicateHouseholdException if an existing owner already shares the household and the
565	     *     create did not declare {@code sharesHousehold}
566	     */
567	    private void requireNoHouseholdDuplicate(Owner owner, boolean declaredHouseholdMember) {
568	        if (declaredHouseholdMember) {
569	            return;
570	        }
571	        String householdId = owner.getHouseholdId();
572	        boolean inUse = this.clinicService.findAllOwners().stream()
573	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
574	        if (inUse) {
575	            throw new DuplicateHouseholdException(householdId);
576	        }
577	    }
578	
579	    /**
580	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
581	     * the household - the existing owners that share the deterministic {@code householdId} and the new
582	     * one - so the shared size can be read back from any of them. The count is the number of existing
583	     * members plus the owner being created.
584	     *
585	     * @param owner the owner being created, with its deterministic {@code householdId} already set
586	     */
587	    private void stampHouseholdSize(Owner owner) {
588	        String householdId = owner.getHouseholdId();
589	        List<Owner> members = this.clinicService.findAllOwners().stream()
590	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
591	            .toList();
592	        int householdSize = members.size() + 1;
593	        owner.setHouseholdSize(householdSize);
594	        for (Owner member : members) {
595	            member.setHouseholdSize(householdSize);
596	            this.clinicService.saveOwner(member);
597	        }
598	    }
599	
600	    /**
601	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
602	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
603	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
604	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
605	     * shares a last name and postcode computes the same identifier and therefore the same household.
606	     *
607	     * @param lastName the last name of the household
608	     * @param postcode the postcode of the household, possibly {@code null}
609	     * @return the 12-character upper-case hex household identifier
610	     */
611	    private String computeHouseholdId(String lastName, String postcode) {
612	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
613	        try {
614	            byte[] digest = MessageDigest.getInstance("SHA-256")
615	                .digest(key.getBytes(StandardCharsets.UTF_8));
616	            StringBuilder hex = new StringBuilder(12);
617	            for (int i = 0; i < 6; i++) {
618	                hex.append(String.format("%02X", digest[i]));
619	            }
620	            return hex.toString();
621	        } catch (NoSuchAlgorithmException e) {
622	            throw new IllegalStateException("SHA-256 algorithm not available", e);
623	        }
624	    }
625	
626	    /**
627	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
628	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
629	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
630	     *
631	     * @param value the raw value, possibly {@code null}
632	     * @return the normalized value
633	     */
634	    private String normalizeForHousehold(String value) {
635	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
636	    }
637	
638	    /**
639	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
640	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
641	     * value yields an empty string.
642	     *
643	     * @param value the raw value, possibly {@code null}
644	     * @return the trimmed, whitespace-collapsed value
645	     */
646	    private String collapseWhitespace(String value) {
647	        if (value == null) {
648	            return "";
649	        }
650	        return value.trim().replaceAll("\\s+", " ");
651	    }
652	
653	    /**
654	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
655	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
656	     * is upper-cased, and common street-type abbreviations are expanded as whole words
657	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
658	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
659	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
660	     *
661	     * @param address the raw address value, possibly {@code null}
662	     * @return the normalized address
663	     */
664	    private String normalizeAddress(String address) {
665	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
666	        if (collapsed.isEmpty()) {
667	            return "";
668	        }
669	        String[] tokens = collapsed.split(" ");
670	        StringBuilder normalized = new StringBuilder();
671	        for (int i = 0; i < tokens.length; i++) {
672	            if (i > 0) {
673	                normalized.append(' ');
674	            }
675	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
676	        }
677	        return normalized.toString();
678	    }
679	
680	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
681	    @Override
682	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
683	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
684	        if (currentOwner == null) {
685	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
686	        }
687	        currentOwner.setAddress(ownerFieldsDto.getAddress());
688	        currentOwner.setCity(ownerFieldsDto.getCity());
689	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
690	        currentOwner.setLastName(ownerFieldsDto.getLastName());
691	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
692	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
693	        this.clinicService.saveOwner(currentOwner);
694	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
695	    }
696	
697	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
698	    @Transactional
699	    @Override
700	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
701	        Owner owner = this.clinicService.findOwnerById(ownerId);
702	        if (owner == null) {
703	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
704	        }
705	        this.clinicService.deleteOwner(owner);
706	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
707	    }
708	
709	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
710	    @Override
711	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
712	        Owner owner = this.clinicService.findOwnerById(ownerId);
713	        if (owner == null) {
714	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
715	        }
716	        HttpHeaders headers = new HttpHeaders();
717	        Pet pet = petMapper.toPet(petFieldsDto);
718	        owner.setId(ownerId);
719	        pet.setOwner(owner);
720	        pet.getType().setName(null);
721	        this.clinicService.savePet(pet);
722	        PetDto petDto = petMapper.toPetDto(pet);
723	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
724	            .buildAndExpand(pet.getId()).toUri());
725	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
726	    }
727	
728	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
729	    @Override
730	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
731	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
732	        if (currentOwner != null) {
733	            Pet currentPet = this.clinicService.findPetById(petId);
734	            if (currentPet != null) {
735	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
736	                currentPet.setName(petFieldsDto.getName());
737	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
738	                this.clinicService.savePet(currentPet);
739	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
740	            }
741	        }
742	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
743	    }
744	
745	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
746	    @Override
747	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
748	        HttpHeaders headers = new HttpHeaders();
749	        Visit visit = visitMapper.toVisit(visitFieldsDto);
750	        Pet pet = new Pet();
751	        pet.setId(petId);
752	        visit.setPet(pet);
753	        this.clinicService.saveVisit(visit);
754	        VisitDto visitDto = visitMapper.toVisitDto(visit);
755	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
756	            .buildAndExpand(visit.getId()).toUri());
757	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
758	    }
759	
760	
761	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
762	    @Override
763	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
764	        Owner owner = this.clinicService.findOwnerById(ownerId);
765	        if (owner != null) {
766	            Pet pet = owner.getPet(petId);
767	            if (pet != null) {
768	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
769	            }
770	        }
771	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
772	    }
773	}
